      CREATE TABLE IF NOT EXISTS locations (
        id TEXT PRIMARY KEY,
        business_id TEXT NOT NULL REFERENCES businesses(id),
        name TEXT NOT NULL,
        address TEXT,
        google_reviews_url TEXT,
        qr_code TEXT
      );
    `);
