      CREATE TABLE IF NOT EXISTS reviews (
        id TEXT PRIMARY KEY,
        business_id TEXT NOT NULL REFERENCES businesses(id),
        location_id TEXT NOT NULL REFERENCES locations(id),
        rating INTEGER NOT NULL,
        feedback_text TEXT,
        contact_requested INTEGER DEFAULT 0,
        contact_name TEXT,
        contact_phone TEXT,
        contact_email TEXT,
